"""Embed the qualified AOT image as a C++ initializer after validating its digest."""
from pathlib import Path
import argparse,hashlib,json

def embed(binary):
    lines=['// DeepSeek MIT-derived TileLang SM120 image; see LICENSE.DeepSeek.',
           '// Generated by examples/kernels2/embed_sparse.py; do not hand edit.',
           '// SHA256: '+hashlib.sha256(binary).hexdigest()]
    lines+=['    '+','.join('0x%02x'%b for b in binary[i:i+24])+',' for i in range(0,len(binary),24)]
    return '\n'.join(lines)+'\n'

if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--cubin',type=Path,required=True)
    p.add_argument('--output',type=Path,required=True)
    p.add_argument('--manifest',type=Path,default=Path(__file__).with_name('native-sparse-image.json'))
    a=p.parse_args();binary=a.cubin.read_bytes();manifest=json.loads(a.manifest.read_text())
    if hashlib.sha256(binary).hexdigest()!=manifest['cubin_sha256']:
        raise ValueError('Image is not the qualified digest; validate and update the manifest first')
    a.output.write_text(embed(binary),encoding='ascii',newline='\n')
